SourceCode.Declaration:
/// <summary>
/// A temporary troubleshooting response - see HSMobileOpsInquiryService::debugPostLog. Not part
/// of the app's real API surface; safe to delete once the HSMobileOpsPostLog duplicate-key issue
/// it exists to diagnose is understood.
/// </summary>
[DataContractAttribute]
class HSMobileOpsDebugResponse
{
    boolean success;
    List    rows;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

/// <summary>
/// One formatted line per HSMobileOpsPostLog row, most recent first.
/// </summary>
[DataMemberAttribute('Rows'),
 DataCollectionAttribute(Types::String)]
public List parmRows(List _value = rows)
{
    rows = _value;
    return rows;
}
